package com.example.dsatracker.controller;import com.example.dsatracker.dto.AuthenticationResponse;import com.example.dsatracker.dto.LoginRequestDTO;import com.example.dsatracker.dto.RegisterRequestDTO;import com.example.dsatracker.service.AuthService;import jakarta.validation.Valid;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/auth")public class AuthController {    private final AuthService service;    public AuthController(AuthService service) {        this.service = service;    }    @PostMapping("/register")    public ResponseEntity<AuthenticationResponse> register(            @Valid @RequestBody RegisterRequestDTO request) {        return ResponseEntity.ok(service.register(request));    }    @PostMapping("/login")    public ResponseEntity<AuthenticationResponse> login(            @Valid @RequestBody LoginRequestDTO request) {        return ResponseEntity.ok(service.login(request));    }}